152:         // cached after); -1 = no mask. Cheap per-frame: a name->layer map lookup.
153:         int cookieLayer = (l.cookie != null && !l.cookie.isEmpty()) ? CookieArray.resolve(l.cookie) : -1;
154:         float cookieFlags = l.cookieInvert ? 1F : 0F;
155: 
156:         LightRegistry.registerSpot(
157:             (float) l.x, (float) l.y, (float) l.z,
158:             dx, dy, dz,
159:             l.r, l.g, l.b,
160:             l.intensity, l.range, cosOuter, cosInner,
161:             l.entitiesOnly, l.blocksOnly,
162:             l.anisotropy, l.vlDensity, l.beamStrength, l.bulbSize,
163:             l.shadows,
