245:     @Override
246:     public boolean scroll(int mx, int my, double amount) {
247:         // If cursor is over the animation panel, delegate to it
248:         if (animationExpanded && animationPanel != null &&
249:             mx >= animationPanel.x && mx < animationPanel.x + animationPanel.w &&
250:             my >= animationPanel.y && my < animationPanel.y + animationPanel.h) {
251:             return animationPanel.scroll(mx, my, amount);
252:         }
253:         // Otherwise scroll the inspector
254:         scrollY += (int)(amount * 16);
255:         if (scrollY > 0) scrollY = 0;
256:         
257:         // Prevent scrolling infinitely downwards
258:         int maxScroll = -800; 
259:         if (scrollY < maxScroll) scrollY = maxScroll;
260:         return true;
261:     }
