263:     @Override
264:     public void render(CLUIContext ctx) {
265:         // Calculate target animated heights for all collapsible inspector sections
266:         float targetTransformH = transformExpanded ? (16 + 3) : 0;
267:         float targetLightH = lightExpanded ? (16 + 3 + 16 + 3 + 16 + 3 + 110 + 3) : 0;
268:         float targetSpecificH = specificExpanded ? (!light.isSpot ? (16 + 3) : (16 + 3 + 16 + 3 + 16 + 3 + 16 + 3)) : 0;
269:         float targetFogH = fogExpanded ? (light.fogEnabled ? (16 + 3 + 16 + 3 + 16 + 3 + 16 + 3) : (16 + 3)) : 0;
270:         float targetShadowH = shadowExpanded ? (light.shadowEnabled ? (16 + 3 + 16 + 3) : (16 + 3)) : 0;
271:         float targetExclusionsH = exclusionsExpanded ? (16 + 3 + 16 + 3) : 0;
