276:         float targetGoboH = showGobo ? (goboExpanded ? ((16 + 3) + (goboSelectorExpanded ? numGobos * (16 + 3) : 0) + (16 + 3) + (16 + 3) + (16 + 3)) : 0) : 0;
277: 
278:         if (transformAnimH < 0) transformAnimH = targetTransformH;
279:         if (lightAnimH < 0) lightAnimH = targetLightH;
280:         if (specificAnimH < 0) specificAnimH = targetSpecificH;
281:         if (fogAnimH < 0) fogAnimH = targetFogH;
