1023:     private int interpolateColor(int c1, int c2, float t) {
1024:         int a1 = (c1 >> 24) & 0xFF;
1025:         int r1 = (c1 >> 16) & 0xFF;
1026:         int g1 = (c1 >> 8) & 0xFF;
1027:         int b1 = c1 & 0xFF;
1028: 
1029:         int a2 = (c2 >> 24) & 0xFF;
1030:         int r2 = (c2 >> 16) & 0xFF;
1031:         int g2 = (c2 >> 8) & 0xFF;
1032:         int b2 = c2 & 0xFF;
1033: 
1034:         int a = (int) (a1 + (a2 - a1) * t);
1035:         int r = (int) (r1 + (r2 - r1) * t);
1036:         int g = (int) (g1 + (g2 - g1) * t);
1037:         int b = (int) (b1 + (b2 - b1) * t);
1038: 
1039:         return (a << 24) | (r << 16) | (g << 8) | b;
1040:     }
