43:     public static void collect(ClientWorld world, Vec3d cameraPos, float tickDelta)
44:     {
45:         if (world == null || cameraPos == null)
46:         {
47:             return;
48:         }
49: 
50:         // Manual lights first, so they keep priority on the limited shadow slots.
51:         // Count manual POINT lights that cast shadows: those compete for the same
52:         // cube-shadow slots the auto-lights would use, so their share is reserved.
53:         int manualShadowPoints = 0;
54:         java.util.List<PlacedLight> lights = LightScene.all();
55:         for (int i = 0, n = lights.size(); i < n; i++)
56:         {
57:             PlacedLight l = lights.get(i);
58:             if (l == null)
59:             {
60:                 continue;
61:             }
62:             if (l.type == PlacedLight.Type.SPOT)
63:             {
64:                 emitSpot(l);
65:             }
66:             else
67:             {
68:                 emitPoint(l);
69:                 if (l.shadows)
70:                 {
71:                     manualShadowPoints++;
72:                 }
73:             }
74:         }
75: 
76:         // Auto block-lights (torch / glowstone / ...), all point lights. Fed AFTER
77:         // the manual lights and capped to the SSBO headroom so a manual light is
78:         // never dropped at the 256-light limit. Only the nearest few cast shadows:
79:         //   - reserve the cube slots manual point lights need (PointShadowArray has
80:         //     MAX_SHADOWS), so an auto-light never starves a manual one of a slot;
81:         //   - ramp the count up over frames so a freshly-lit area doesn't first-bake
82:         //     every cube in a single frame.
83:         // Nearest-first feed means the closest emitters win the shadow grants.
84:         if (LightConfig.autoLights())
85:         {
