96:             // ineligible ones (e.g. redstone dust) never consume a slot.
97:             int granted = 0;
98:             for (int i = 0, n = autos.size(); i < n; i++)
99:             {
100:                 PlacedLight l = autos.get(i);
101:                 if (l == null)
102:                 {
103:                     continue;
104:                 }
105:                 boolean wantShadow = l.autoShadowEligible && granted < shadowBudget;
106:                 l.shadows = wantShadow;
107:                 if (wantShadow)
108:                 {
