package elgatopro300.cal_lights.manager;

import elgatopro300.cal_lights.animation.LightAnimation;

public class LightInstance {
    public final int id;
    public String name = "";
    public boolean isSpot = false;
    public boolean visible = true;

    // Position
    public float x, y, z;

    // Color (R, G, B floats 0-1)
    public float r = 1f;
    public float g = 1f;
    public float b = 1f;

    // Intensity (0..20)
    public float intensity = 1.0f;

    // Point light radius (0.1..64)
    public float radius = 6.0f;

    // Spot light properties
    public float dx = 0f;
    public float dy = -1f;
    public float dz = 0f; // pointing down by default

    // Spot cone: angle = outer cone full angle in degrees (1..179),
    //            soft  = penumbra width in degrees (0..60).
    // innerAngle is derived: max(1, angle - soft).
    // This matches the original IRL editor exactly.
    public float angle = 35.0f;     // outer cone full angle (degrees)
    public float soft  = 10.0f;     // penumbra/softness width (degrees)
    public float distance = 12.0f;  // spot range in blocks (0.1..128)

    // Spot light rotations (X, Y, Z in degrees, convenience for editor UI)
    public float rx = -90f;
    public float ry = 0f;
    public float rz = 0f;

    // Volumetric Fog properties
    // These map to the IRL Core API as:
    //   fogEnabled -> controls whether beamStrength is sent (beam or 0)
    //   beamStrength -> bm parameter (0..5)
    //   vlDensity -> dens parameter (0.005..0.5)
    //   anisotropy -> aniso parameter (-0.95..0.95)
    public boolean fogEnabled = true;
    public float beamStrength = 1.0f;    // volumetric beam strength (0..5)
    public float vlDensity = 0.05f;      // volumetric density (0.005..0.5)
    public float anisotropy = 0.4f;      // Henyey-Greenstein g (-0.95..0.95)

    // Shadow properties
    // bulbSize maps to the 'bulb' parameter in IRL Core (0..2)
    // This controls shadow softness (0 = hard / shader global, 2 = very soft)
    public boolean shadowEnabled = true;
    public float bulbSize = 0.0f;        // shadow softness / penumbra (0..2)

    // Exclusions
    public boolean entitiesOnly = false;
    public boolean blocksOnly = false;

    // Gobo properties
    public String goboName = "None";
    public float goboRotation = 0.0f;    // degrees in UI, converted to radians for API
    public float cookieScale = 1.0f;
    public boolean cookieInvert = false;

    // Coordinates specialized for shaders (replays/model blocks)
    public Float shaderX = null;
    public Float shaderY = null;
    public Float shaderZ = null;
    public Float shaderDx = null;
    public Float shaderDy = null;
    public Float shaderDz = null;

    public float getShaderX() { return shaderX != null ? shaderX : x; }
    public float getShaderY() { return shaderY != null ? shaderY : y; }
    public float getShaderZ() { return shaderZ != null ? shaderZ : z; }
    public float getShaderDx() { return shaderDx != null ? shaderDx : dx; }
    public float getShaderDy() { return shaderDy != null ? shaderDy : dy; }
    public float getShaderDz() { return shaderDz != null ? shaderDz : dz; }

    /** Derived outer angle in degrees (= angle). */
    public float getOuterAngleDeg() {
        return angle;
    }

    /** Derived inner angle in degrees = max(1, angle - soft), clamped to <= angle. */
    public float getInnerAngleDeg() {
        float inner = Math.max(1f, angle - soft);
        return Math.min(inner, angle);
    }

    public int counter = 2; // lifecycle ticks
    public boolean persistent = false; // if true, won't be deleted by tick() decrement

    // Animation
    /** Optional animation state. When non-null and enabled, overrides live values every tick. */
    public LightAnimation animation = null;

    public LightInstance(int id) {
        this.id = id;
    }

    public void mark() {
        this.counter = 2; // stays alive for 2 ticks (prevents deletion on frame gaps)
    }

    public void setPoint(float x, float y, float z, float r, float g, float b, float intensity, float radius) {
        this.isSpot = false;
        this.x = x; this.y = y; this.z = z;
        this.r = r; this.g = g; this.b = b;
        this.intensity = intensity;
        this.radius = radius;
        this.shaderX = null;
        this.shaderY = null;
        this.shaderZ = null;
        this.shaderDx = null;
        this.shaderDy = null;
        this.shaderDz = null;
    }

    public void setSpot(float x, float y, float z, float dx, float dy, float dz, float r, float g, float b, float intensity, float angle, float soft, float distance) {
        this.isSpot = true;
        this.x = x; this.y = y; this.z = z;
        this.dx = dx; this.dy = dy; this.dz = dz;
        this.r = r; this.g = g; this.b = b;
        this.intensity = intensity;
        this.angle = angle;
        this.soft = soft;
        this.distance = distance;
        this.shaderX = null;
        this.shaderY = null;
        this.shaderZ = null;
        this.shaderDx = null;
        this.shaderDy = null;
        this.shaderDz = null;

        // Synchronize rotation Euler angles from the loaded direction vector
        float len = (float) Math.sqrt(dx * dx + dy * dy + dz * dz);
        if (len > 0.0001f) {
            float ndx = dx / len;
            float ndy = dy / len;
            float ndz = dz / len;
            this.rx = (float) Math.toDegrees(Math.asin(ndy));
            this.ry = (float) Math.toDegrees(Math.atan2(-ndx, -ndz));
            if (this.ry < 0) this.ry += 360.0f;
        } else {
            this.rx = -90f;
            this.ry = 0f;
        }
        this.rz = 0f;
    }
}

package elgatopro300.cal_lights;

import elgatopro300.cal_lights.gizmo.LightGizmo;
import elgatopro300.cal_lights.graphics.CalLightsIcons;
import elgatopro300.cal_lights.manager.GoboManager;
import elgatopro300.cal_lights.manager.LightInstance;
import elgatopro300.cal_lights.manager.LightManager;
import elgatopro300.cal_lights.manager.LightSaveManager;
import org.qualet.irl.light.LightRegistry;
import elgatopro300.cal_lights.ui.CALEditorScreen;

import net.fabricmc.api.ClientModInitializer;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientLifecycleEvents;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.fabricmc.fabric.api.client.keybinding.v1.KeyBindingHelper;
import net.fabricmc.fabric.api.client.rendering.v1.WorldRenderEvents;

import net.minecraft.client.option.KeyBinding;
import net.minecraft.client.util.InputUtil;
import net.minecraft.text.Text;
import net.minecraft.util.math.Vec3d;

import org.lwjgl.glfw.GLFW;

import java.util.concurrent.ThreadLocalRandom;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class CALLightsClient implements ClientModInitializer {
    public static final Logger LOGGER = LoggerFactory.getLogger("CAL Lights Client");
    public static KeyBinding editorKeyBinding;
    public static KeyBinding createLightKeyBinding;

    private static final int AUTO_SHADOW_RAMP_STEP = 2;
    private static int autoShadowRamp = 0;

    @Override
    public void onInitializeClient() {
        LOGGER.info("CAL Lights mod initialized on Client!");

        // Install the patcher host so the shared irl-core patcher can reach the game
        // dir / Iris shaderpacks dir / bundled .irlights patches.
        org.qualet.irl.patcher.Patcher.install(new elgatopro300.cal_lights.patcher.CALPatcherHost());

        editorKeyBinding = KeyBindingHelper.registerKeyBinding(new KeyBinding(
            "key.cal.editor",
            InputUtil.Type.KEYSYM,
            GLFW.GLFW_KEY_F8,
            "category.cal"
        ));

        createLightKeyBinding = KeyBindingHelper.registerKeyBinding(new KeyBinding(
            "key.cal.create_light",
            InputUtil.Type.KEYSYM,
            GLFW.GLFW_KEY_F7,
            "category.cal"
        ));

        ClientLifecycleEvents.CLIENT_STARTED.register(client -> {
            LOGGER.info("Initializing CAL Lights Icons...");
            CalLightsIcons.init();

            LOGGER.info("Initializing CAL Lights 3D Gizmo...");
            LightGizmo.INSTANCE.init();

            LOGGER.info("Initializing CAL Lights Gobo Manager...");
            GoboManager.INSTANCE.init();
        });

        ClientTickEvents.END_CLIENT_TICK.register(client -> {
            LightSaveManager.tick(client);
            LightManager.INSTANCE.tick();

            if (client.world != null && client.player != null) {
                elgatopro300.cal_lights.light.auto.AutoLightManager.tick(client.world,
                    client.player.getX(), client.player.getEyeY(), client.player.getZ());
            }

            while (editorKeyBinding.wasPressed()) {
                if (client.player != null) {
                    client.setScreen(new CALEditorScreen());
                }
            }

            while (createLightKeyBinding.wasPressed()) {
                if (client.player != null) {
                    Vec3d p = client.gameRenderer.getCamera().getPos();
                    int id = ThreadLocalRandom.current().nextInt(100000, 999999);
                    boolean isSpot = ThreadLocalRandom.current().nextBoolean();
                    if (isSpot) {
                        // angle=35, soft=10, distance=12 (IRL defaults)
                        LightInstance light = LightManager.INSTANCE.updateSpot(id, (float) p.x, (float) p.y, (float) p.z, 0f, -1f, 0f, 1f, 1f, 1f, 1.0f, 35.0f, 10.0f, 12.0f);
                        light.persistent = true;
                        client.player.sendMessage(Text.literal("Created Spot Light: " + id), true);
                    } else {
                        LightInstance light = LightManager.INSTANCE.updatePoint(id, (float) p.x, (float) p.y, (float) p.z, 1f, 1f, 1f, 1.0f, 6.0f);
                        light.persistent = true;
                        client.player.sendMessage(Text.literal("Created Point Light: " + id), true);
                    }
                }
            }
        });

        WorldRenderEvents.BEFORE_ENTITIES.register(context -> {
            GoboManager.INSTANCE.bind();
            registerLightsToIrlCore();
        });
    }

    /**
     * Feeds all managed lights (manual + auto) into the IRL Core LightRegistry
     * each frame. The parameter mapping matches the original IRL editor's
     * LightDriver exactly:
     *
     * Point: registerPoint(x, y, z, r, g, b, intensity, radius,
     *            entitiesOnly, blocksOnly, anisotropy, vlDensity,
     *            beamStrength, bulbSize, shadows, id)
     *
     * Spot:  registerSpot(x, y, z, dx, dy, dz, r, g, b, intensity,
     *            range, cosOuter, cosInner, entitiesOnly, blocksOnly,
     *            anisotropy, vlDensity, beamStrength, bulbSize, shadows,
     *            cookieLayer, cookieRot, cookieScale, cookieFlags, id)
     */
    private static void registerLightsToIrlCore() {
        LightRegistry.clear();

        // 1. Point lights
        for (LightInstance l : LightManager.INSTANCE.getPointLights()) {
            if (l.visible) {
                // beamStrength is 0 when volumetrics are disabled
                float bm = l.fogEnabled ? l.beamStrength : 0.0f;

                LightRegistry.registerPoint(
                    l.x, l.y, l.z,
                    l.r, l.g, l.b,
                    l.intensity, l.radius,
                    l.entitiesOnly, l.blocksOnly,
                    l.anisotropy, l.vlDensity, bm, l.bulbSize,
                    l.shadowEnabled, (long) l.id
                );
            }
        }

        // 2. Spot lights
        for (LightInstance l : LightManager.INSTANCE.getSpotLights()) {
            if (l.visible) {
                float sdx = l.dx, sdy = l.dy, sdz = l.dz;
                float len = (float) Math.sqrt(sdx * sdx + sdy * sdy + sdz * sdz);
                if (len > 1e-4f) {
                    sdx /= len;
                    sdy /= len;
                    sdz /= len;
                } else {
                    sdx = 0f;
                    sdy = -1f;
                    sdz = 0f;
                }

                // Derive inner/outer from angle + soft, exactly as the original:
                // outer = angle, inner = clamp(angle - soft, 1, angle)
                float outer = l.getOuterAngleDeg();
                float inner = l.getInnerAngleDeg();
                float cosOuter = (float) Math.cos(Math.toRadians(outer * 0.5f));
                float cosInner = (float) Math.cos(Math.toRadians(inner * 0.5f));

                int cookieLayer = GoboManager.INSTANCE.getGoboIndex(l.goboName);
                // Cookie rotation: stored in degrees in UI, passed in radians to API
                float cookieRot = (float) Math.toRadians(l.goboRotation);
                float cookieScale = l.cookieScale;
                float cookieFlags = l.cookieInvert ? 1.0f : 0.0f;

                // beamStrength is 0 when volumetrics are disabled
                float bm = l.fogEnabled ? l.beamStrength : 0.0f;

                LightRegistry.registerSpot(
                    l.x, l.y, l.z,
                    sdx, sdy, sdz,
                    l.r, l.g, l.b,
                    l.intensity, l.distance, cosOuter, cosInner,
                    l.entitiesOnly, l.blocksOnly,
                    l.anisotropy, l.vlDensity, bm, l.bulbSize,
                    l.shadowEnabled,
                    (float) cookieLayer, cookieRot, cookieScale, cookieFlags,
                    (long) l.id
                );
            }
        }

        // 3. Auto block-lights
        if (elgatopro300.cal_lights.light.LightConfig.autoLights()) {
            net.minecraft.client.MinecraftClient mc = net.minecraft.client.MinecraftClient.getInstance();
            if (mc.player != null && mc.world != null) {
                Vec3d cameraPos = mc.gameRenderer.getCamera().getPos();

                int headroom = Math.max(0, org.qualet.irl.light.LightBuffer.MAX_LIGHTS - LightRegistry.getCount());
                int feedMax = Math.min(elgatopro300.cal_lights.light.LightConfig.autoLightMax(), headroom);

                int manualShadowPoints = 0;
                for (LightInstance l : LightManager.INSTANCE.getPointLights()) {
                    if (l.visible && l.shadowEnabled) {
                        manualShadowPoints++;
                    }
                }

                autoShadowRamp = Math.min(16, autoShadowRamp + AUTO_SHADOW_RAMP_STEP);
                int shadowBudget = elgatopro300.cal_lights.light.LightConfig.autoLightShadows()
                    ? Math.min(autoShadowRamp, Math.max(0, 16 - manualShadowPoints))
                    : 0;

                java.util.List<elgatopro300.cal_lights.light.PlacedLight> autos =
                    elgatopro300.cal_lights.light.auto.AutoLightManager.nearest(cameraPos, feedMax);

                int granted = 0;
                for (elgatopro300.cal_lights.light.PlacedLight l : autos) {
                    if (l == null) continue;
                    boolean wantShadow = l.autoShadowEligible && granted < shadowBudget;
                    l.shadows = wantShadow;
                    if (wantShadow) {
                        granted++;
                    }

                    LightRegistry.registerPoint(
                        (float) l.x, (float) l.y, (float) l.z,
                        l.r, l.g, l.b,
                        l.intensity, l.radius,
                        l.entitiesOnly, l.blocksOnly,
                        l.anisotropy, l.vlDensity, l.beamStrength, l.bulbSize,
                        l.shadows, l.id
                    );
                }
            }
        } else {
            autoShadowRamp = 0;
        }

        LightRegistry.flush();
    }
}

