116:     private static void emitPoint(PlacedLight l)
117:     {
118:         LightRegistry.registerPoint(
119:             (float) l.x, (float) l.y, (float) l.z,
120:             l.r, l.g, l.b,
121:             l.intensity, l.radius,
122:             l.entitiesOnly, l.blocksOnly,
123:             l.anisotropy, l.vlDensity, l.beamStrength, l.bulbSize,
124:             l.shadows, l.id);
125:     }
