127:     private static void emitSpot(PlacedLight l)
128:     {
129:         // Normalize the world-space direction defensively (matches LightCollector).
130:         float dx = l.dirX, dy = l.dirY, dz = l.dirZ;
131:         float len = (float) Math.sqrt(dx * dx + dy * dy + dz * dz);
132:         if (len > 1e-4f)
133:         {
134:             dx /= len;
135:             dy /= len;
136:             dz /= len;
137:         }
138:         else
139:         {
140:             dx = 0f;
141:             dy = 0f;
142:             dz = 1f;
143:         }
144: 
145:         // Full cone angles (degrees) -> half-angle cosines, exactly as IRLite did.
146:         float outer = l.outerAngleDeg;
147:         float inner = Math.min(l.innerAngleDeg, outer);
148:         float cosOuter = (float) Math.cos(Math.toRadians(outer * 0.5F));
149:         float cosInner = (float) Math.cos(Math.toRadians(inner * 0.5F));
150: 
151:         // Resolve the gobo image to its texture-array layer (loads on first use,
152:         // cached after); -1 = no mask. Cheap per-frame: a name->layer map lookup.
153:         int cookieLayer = (l.cookie != null && !l.cookie.isEmpty()) ? CookieArray.resolve(l.cookie) : -1;
154:         float cookieFlags = l.cookieInvert ? 1F : 0F;
155: 
156:         LightRegistry.registerSpot(
157:             (float) l.x, (float) l.y, (float) l.z,
158:             dx, dy, dz,
159:             l.r, l.g, l.b,
