179:         float radZ = (float) Math.toRadians(light.rz);
180:         // Rotate (0, 0, -1) by XYZ Euler
181:         float cosX = (float) Math.cos(radX), sinX = (float) Math.sin(radX);
182:         float cosY = (float) Math.cos(radY), sinY = (float) Math.sin(radY);
183:         float cosZ = (float) Math.cos(radZ), sinZ = (float) Math.sin(radZ);
184:         float y1 = -(-1f) * sinX, z1 = (-1f) * cosX, x1 = 0f;
185:         float x2 = x1 * cosY + z1 * sinY, y2 = y1, z2 = -x1 * sinY + z1 * cosY;
