737:     @Override
738:     public boolean mouseClicked(int mx, int my, int btn) {
739:         // Adjust coordinate context for mouse clicking based on scrolling offset
740:         int relativeMy = my - scrollY;
741: 
742:         int currentY = y + 25;
743:         int headerH = 18;
744:         int elementH = 16;
745:         int gap = 3;
746: 
747:         // 6. Animation accordion toggle (now at the very top!)
748:         if (mx >= x + 8 && mx < x + w - 8 && relativeMy >= currentY && relativeMy < currentY + headerH) {
749:             animationExpanded = !animationExpanded;
750:             return true;
751:         }
752:         currentY += headerH + gap;
753:         if (animationExpanded) {
754:             // Animation enabled toggle
755:             if (animationSwitch.mouseClicked(mx, my, btn)) return true;
756:         }
757:         currentY += (int) animationAnimH;
758: 
759:         // 1. Transform expanded toggle click
760:         if (mx >= x + 8 && mx < x + w - 8 && relativeMy >= currentY && relativeMy < currentY + headerH) {
761:             transformExpanded = !transformExpanded;
762:             return true;
763:         }
764:         currentY += headerH + gap;
765:         if (transformExpanded) {
766:             if (trackX.mouseClicked(mx, my, btn) || 
767:                 trackY.mouseClicked(mx, my, btn) || 
768:                 trackZ.mouseClicked(mx, my, btn)) {
769:                 return true;
770:             }
771:             int drawY = currentY + elementH + gap;
772:             if (mx >= x + 10 && mx < x + w - 10 && relativeMy >= drawY && relativeMy < drawY + elementH) {
773:                 MinecraftClient mc = MinecraftClient.getInstance();
774:                 if (mc.player != null) {
775:                     CALUndoManager.pushState();
776:                     light.x = (float) mc.player.getX();
