126:     private static void drawSpot(BufferBuilder buf, Matrix4f m, float x, float y, float z, PlacedLight l, float r, float g, float b)
127:     {
128:         // Normalized direction (defaults straight down, matching the driver).
129:         float dx = l.dirX, dy = l.dirY, dz = l.dirZ;
130:         float dlen = (float) Math.sqrt(dx * dx + dy * dy + dz * dz);
131:         if (dlen < 1e-4f)
132:         {
133:             dx = 0f; dy = -1f; dz = 0f; dlen = 1f;
134:         }
135:         dx /= dlen; dy /= dlen; dz /= dlen;
136: 
137:         float len = Math.max(1f, Math.min(l.range, MAX_CONE_LEN));
138:         float radius = (float) (len * Math.tan(Math.toRadians(l.outerAngleDeg * 0.5f)));
139: 
140:         // End-cap centre.
141:         float ex = x + dx * len, ey = y + dy * len, ez = z + dz * len;
142: 
143:         // Orthonormal basis (u, v) spanning the end-cap plane.
144:         float rx, ry, rz;
145:         if (Math.abs(dy) < 0.99f) { rx = 0f; ry = 1f; rz = 0f; }
146:         else { rx = 1f; ry = 0f; rz = 0f; }
147:         float ux = dy * rz - dz * ry, uy = dz * rx - dx * rz, uz = dx * ry - dy * rx;
148:         float ul = (float) Math.sqrt(ux * ux + uy * uy + uz * uz);
149:         ux /= ul; uy /= ul; uz /= ul;
150:         float vx = dy * uz - dz * uy, vy = dz * ux - dx * uz, vz = dx * uy - dy * ux;
151: 
152:         // Centre axis line (the direction indicator).
153:         line(buf, m, x, y, z, ex, ey, ez, r, g, b);
154: 
155:         // End ring + spokes from the apex.
156:         float px = 0f, py = 0f, pz = 0f;
157:         for (int i = 0; i <= CONE_SEGMENTS; i++)
158:         {
159:             double a = (Math.PI * 2.0) * i / CONE_SEGMENTS;
160:             float cos = (float) Math.cos(a), sin = (float) Math.sin(a);
161:             float qx = ex + (ux * cos + vx * sin) * radius;
162:             float qy = ey + (uy * cos + vy * sin) * radius;
163:             float qz = ez + (uz * cos + vz * sin) * radius;
164: 
165:             if (i > 0)
166:             {
167:                 line(buf, m, px, py, pz, qx, qy, qz, r, g, b);
168:             }
169:             if (i % (CONE_SEGMENTS / CONE_SPOKES) == 0)
170:             {
171:                 line(buf, m, x, y, z, qx, qy, qz, r, g, b);
172:             }
173:             px = qx; py = qy; pz = qz;
174:         }
175:     }
