648:     /**
649:      * Draws an ImGuizmo handle at the selected light and writes any drag back into
650:      * {@code state}. Point lights get a translate handle; spotlights get translate
651:      * + rotate rings, with the dragged orientation read back into {@code state.dir}
652:      * (the engine model stays a plain direction vector — no orientation is stored
653:      * on {@code PlacedLight}).
654:      *
655:      * <p>The view/projection matrices are reconstructed to mirror Minecraft's world
656:      * camera exactly (rotation Rx(pitch)·Ry(yaw+180); a perspective with the current
657:      * vertical FOV + framebuffer aspect), so the gizmo lines up with the rendered
658:      * world. Near/far don't affect the on-screen x/y of a projected point, so the
659:      * placeholder far plane is harmless.</p>
660:      */
661:     private void drawGizmo()
662:     {
663:         MinecraftClient mc = MinecraftClient.getInstance();
664:         Camera cam = mc.gameRenderer == null ? null : mc.gameRenderer.getCamera();
665:         if (cam == null || mc.world == null || mc.getWindow().getFramebufferHeight() == 0)
666:         {
667:             return;
668:         }
669: 
670:         boolean spot = state.type == LightState.Type.SPOT;
671:         Vec3d cp = cam.getPos();
672:         float aspect = (float) mc.getWindow().getFramebufferWidth() / (float) mc.getWindow().getFramebufferHeight();
673:         double fovDeg = mc.options.getFov().getValue();
674: 
675:         // View = camera rotation only; world is kept camera-relative via the model.
676:         mat.identity()
677:             .rotateX((float) Math.toRadians(cam.getPitch()))
678:             .rotateY((float) Math.toRadians(cam.getYaw() + 180.0));
679:         mat.get(gizmoView);
680: 
681:         mat.identity().perspective((float) Math.toRadians(fovDeg), aspect, 0.05f, 1000f);
682:         mat.get(gizmoProj);
683: 
684:         // Model = translate to the light (camera-relative, float-safe) · orientation.
685:         mat.identity().translation(
686:             (float) (state.pos[0] - cp.x),
687:             (float) (state.pos[1] - cp.y),
688:             (float) (state.pos[2] - cp.z));
689:         if (spot)
690:         {
691:             // Sync the orientation from dir except while actively rotating (keeps a
692:             // rotate drag continuous instead of snapping back to a canonical roll).
693:             if (!gizmoRotating)
694:             {
695:                 orientationFromDir();
696:             }
697:             mat.mul(gizmoRot);
698:         }
699:         mat.get(gizmoModel);
700: 
701:         int op = spot ? (Operation.TRANSLATE | Operation.ROTATE) : Operation.TRANSLATE;
702:         ImGuizmo.setOrthographic(false);
703:         ImGuizmo.setDrawList(ImGui.getBackgroundDrawList());
704:         ImGuizmo.setRect(0f, 0f, ImGui.getIO().getDisplaySizeX(), ImGui.getIO().getDisplaySizeY());
705:         ImGuizmo.setGizmoSizeClipSpace(GIZMO_SIZE); // a touch smaller than default 0.1
706:         ImGuizmo.allowAxisFlip(false);              // steady axes, no flip toward camera
707:         ImGuizmo.manipulate(gizmoView, gizmoProj, op, Mode.WORLD, gizmoModel);
708: 
709:         boolean using = ImGuizmo.isUsing();
710:         if (using)
711:         {
712:             state.pos[0] = (float) (cp.x + gizmoModel[12]);
713:             state.pos[1] = (float) (cp.y + gizmoModel[13]);
714:             state.pos[2] = (float) (cp.z + gizmoModel[14]);
715: 
716:             if (spot)
717:             {
718:                 // dir = the model's forward (local +Z) column, normalized.
719:                 float dx = gizmoModel[8], dy = gizmoModel[9], dz = gizmoModel[10];
720:                 float len = (float) Math.sqrt(dx * dx + dy * dy + dz * dz);
721:                 if (len > 1e-4f)
722:                 {
723:                     state.dir[0] = dx / len;
724:                     state.dir[1] = dy / len;
725:                     state.dir[2] = dz / len;
726:                 }
727:                 // Persist the manipulated rotation for next frame's continuity.
728:                 gizmoRot.set(gizmoModel).setTranslation(0f, 0f, 0f);
729:             }
730:         }
731: 
732:         gizmoRotating = using && spot;
733:     }
