735:     /** Rebuilds {@link #gizmoRot} as the rotation taking local +Z to {@code state.dir}. */
736:     private void orientationFromDir()
737:     {
738:         float dx = state.dir[0], dy = state.dir[1], dz = state.dir[2];
739:         float len = (float) Math.sqrt(dx * dx + dy * dy + dz * dz);
740:         if (len < 1e-4f)
741:         {
742:             dx = 0f; dy = -1f; dz = 0f; len = 1f;
743:         }
744:         gizmoQuat.rotationTo(0f, 0f, 1f, dx / len, dy / len, dz / len);
745:         gizmoRot.rotation(gizmoQuat);
