18: /**
19:  * In-world wireframe guides for the placed lights, gated by
20:  * {@link LightConfig#showGuides} (the "Показывать гайды" toggle). Spotlights draw
21:  * a cone along their {@code dir} (so direction + beam spread are visible); point
22:  * lights draw a small position cross. The BBS-free stand-in for IRLite's dropped
23:  * {@code LightGuideRenderer}.
24:  *
25:  * <p>Drawn at {@code LAST} (after Iris has composited the frame into the main
26:  * framebuffer) with depth test off (always visible), in camera-relative
27:  * coordinates transformed by the world matrix. Using {@code LAST} rather than
28:  * {@code AFTER_TRANSLUCENT} is what makes the guides survive shaders: at the
29:  * earlier hook the lines land inside the shaderpack's gbuffer/translucent pass and
30:  * get discarded by the deferred composite.</p>
31:  */
32: public final class LightGuideRenderer
33: {
34:     private static final int CONE_SEGMENTS = 20;
35:     private static final int CONE_SPOKES = 4;
36:     private static final float POINT_CROSS = 0.4f;
37:     private static final float MAX_CONE_LEN = 16f;
38: 
39:     private LightGuideRenderer()
40:     {}
41: 
42:     public static void register()
43:     {
44:         // LAST = after Iris composites the world, so the guides survive shaders.
45:         WorldRenderEvents.LAST.register(LightGuideRenderer::onRender);
46:     }
47: 
48:     private static void onRender(WorldRenderContext ctx)
49:     {
50:         if (!LightConfig.showGuides || LightScene.count() == 0)
51:         {
52:             return;
53:         }
54: 
55:         Camera cam = ctx.camera();
56:         if (cam == null)
57:         {
58:             return;
59:         }
60: 
61:         Vec3d c = cam.getPos();
62:         // World camera-rotation matrix: use the event's stack when present, else
63:         // reconstruct it (Rx(pitch)·Ry(yaw+180)) exactly like the move gizmo does.
64:         MatrixStack ms = ctx.matrixStack();
65:         Matrix4f m = ms != null
66:             ? ms.peek().getPositionMatrix()
67:             : new Matrix4f()
68:                 .rotateX((float) Math.toRadians(cam.getPitch()))
69:                 .rotateY((float) Math.toRadians(cam.getYaw() + 180.0));
70: 
71:         RenderSystem.setShader(GameRenderer::getPositionColorProgram);
72:         RenderSystem.enableBlend();
73:         RenderSystem.defaultBlendFunc();
74:         RenderSystem.disableDepthTest(); // guides stay visible through geometry
75:         RenderSystem.disableCull();
76:         RenderSystem.lineWidth(2.0f);
77: 
78:         // 1.21: Tessellator.getBuffer()/BufferBuilder.begin() are gone — begin()
79:         // moved to Tessellator and returns the builder directly.
80:         BufferBuilder buf = Tessellator.getInstance()
81:             .begin(VertexFormat.DrawMode.DEBUG_LINES, VertexFormats.POSITION_COLOR);
82: 
83:         for (PlacedLight l : LightScene.all())
84:         {
85:             if (l == null)
86:             {
87:                 continue;
88:             }
89: 
90:             float r = vis(l.r), g = vis(l.g), b = vis(l.b);
91:             float x = (float) (l.x - c.x);
92:             float y = (float) (l.y - c.y);
93:             float z = (float) (l.z - c.z);
94: 
95:             if (l.type == PlacedLight.Type.SPOT)
96:             {
97:                 drawSpot(buf, m, x, y, z, l, r, g, b);
98:             }
99:             else
100:             {
101:                 drawPoint(buf, m, x, y, z, r, g, b);
102:             }
103:         }
104: 
105:         // 1.21: Tessellator.draw() is gone — build the buffer and submit it through
106:         // BufferRenderer with the bound global program. endNullable() yields null
107:         // when no light produced vertices, so guard the draw.
108:         BuiltBuffer built = buf.endNullable();
109:         if (built != null)
110:         {
111:             BufferRenderer.drawWithGlobalProgram(built);
112:         }
113: 
114:         RenderSystem.lineWidth(1.0f);
115:         RenderSystem.enableCull();
116:         RenderSystem.enableDepthTest();
117:     }
